package com.tcem.common.model.confirmation;

import com.fasterxml.jackson.annotation.JsonInclude;
import com.tcem.common.constants.ConfirmationStatus;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.time.Instant;

/**
 * Confirmation record generated by the validation-service (FR6).
 * <p>
 * Stored in CouchDB ({@code confirmations} database) and linked to the trade by
 * {@code tradeId}. Published to the {@code confirmation.generated} Kafka topic.
 * </p>
 *
 * <h3>Duplicate suppression</h3>
 * Before writing a new confirmation, the validation-service computes the
 * {@link com.tcem.common.registry.ConfirmationFingerprint} over the confirmable
 * fields of the new trade version and compares it against
 * {@code previousConfirmationFingerprint}. If they match, no new confirmation is
 * emitted (the "nothing changed = don't resend" rule).
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
@JsonInclude(JsonInclude.Include.NON_NULL)
public class ConfirmationRecord {

    /** Platform-generated unique ID for this confirmation. Example: {@code CONF-20001} */
    private String confirmationId;

    /** The trade this confirmation applies to. */
    private String tradeId;

    /**
     * Trade version that generated this confirmation.
     * Used to detect whether a new amendment requires a new confirmation.
     */
    private int tradeVersion;

    /** ID of the message that triggered this confirmation. */
    private String sourceMessageId;

    /** Confirmation template used to generate this output. */
    private String templateId;

    /** Template version used. Compared against {@code trade.enrichmentMetadata.resolvedTemplateVersion}. */
    private String templateVersion;

    /** Current status of the confirmation. */
    private ConfirmationStatus status;

    /**
     * SHA-256 hex hash of the confirmable fields at the time this confirmation was generated.
     * <p>
     * Computed by {@link com.tcem.common.registry.ConfirmationFingerprint}.
     * Stored so that the next amendment can compare without re-fetching the full record.
     * </p>
     */
    private String confirmationFingerprint;

    /**
     * Fingerprint of the previous confirmation for this trade, if any.
     * Null on the first confirmation. When present, if the new fingerprint equals
     * this value, the validation-service skips re-confirmation.
     */
    private String previousConfirmationFingerprint;

    /**
     * Rendered confirmation body.
     * Format: plain text or simplified HTML (spec §7 FR6).
     */
    private String confirmationBody;

    /** UTC timestamp when this confirmation was generated. */
    private Instant generatedAt;

    /** Service that generated this record. */
    private String generatedBy;
}
